package cli

// commandHelp contains human-facing usage; agent instructions live in the skill catalog.
var commandHelp = map[string]struct{ usage, note string }{
	"minion":         {"minion dev [CONFIG] [--port PORT]\nminion prepare [CONFIG]\nminion build [CONFIG]\nminion install [--directory DIRECTORY] [--file PACKAGE.tgz]", "Create an app with hostlier init --package minion in the app directory. Add --ui for the React starter.\nCONFIG defaults to minion.json; --file CONFIG is also accepted. Requires Node.js 24+.\nInstalls the bundled framework when needed; local development needs no Hostlier controller."},
	"deploy":         {"deploy [--file FILE] [--package NAME] [--architecture amd64|arm64] [--route ADDRESS] [--server NAME] [--on HOST] [--detach]", "--package selects a local project package even without init. Saved package selections are used on ordinary deploys.\nFrom a Minion app directory, deploy installs Minion if missing, builds from source, and requests Fused consent if needed. Pass --file to deploy a prepared project directly.\n--route overrides the public address.\nLocal source.container inputs are built or packaged and uploaded by the CLI.\nReview the deployment plan and complete the requested approval.\n--detach returns after acceptance; follow with hostlier operation ID --watch."},
	"update":         {"update [--file FILE] [--route ADDRESS] [--server NAME] [--detach]", "Deploy the updated project through the same plan and approval flow as deploy."},
	"rollback":       {"rollback APP [--revision ID] [--server NAME] [--detach]", "Defaults to the revision immediately before the active deployment.\nInspect history with hostlier status APP --json. Approval is required.\nRollback does not undo application or database data changes."},
	"list":           {"list [--all] [--server NAME] [--json]", "Deleted apps are hidden by default. Use --all to inspect retained records before purging them."},
	"status":         {"status [APP] [--server NAME] [--json]", "Omit APP for controller-wide status."},
	"logs":           {"logs APP [--component NAME] [--tail N] [--follow] [--server NAME]", "--component selects a sidecar. --tail accepts 0–10000 lines.\n--follow continues streaming; Ctrl-C stops following."},
	"start":          {"start APP [--server NAME]", ""},
	"stop":           {"stop APP [--server NAME]", "Stops capacity across restarts while retaining containers, images, and data."},
	"restart":        {"restart APP [--server NAME]", "Application data is retained."},
	"delete":         {"delete APP [--purge] [--server NAME]", "Removes owned containers and releases unused images. Data remains unless --purge removes it permanently."},
	"validate":       {"validate [--file FILE]", "Validate the project locally. --file defaults to .hostlier.\nSchema and examples: hostlier skills show deploy"},
	"plan":           {"plan [--file FILE] [--package NAME] [--architecture amd64|arm64] [--route ADDRESS] [--server NAME]", "Preview a selected package locally without building or uploading artifacts. For ordinary projects, preview the controller deployment plan. --file selects a prepared project."},
	"scale":          {"scale APP [--replicas N] [--cpu CORES] [--memory SIZE] [--server NAME]", "Supply at least one capacity option. Manual scale replaces automatic scaling.\nFor idle HTTP services, set sleepAfter: 10m in .hostlier and deploy. The first request wakes the service."},
	"usage":          {"usage APP [--server NAME]", ""},
	"sidecar":        {"sidecar attach APP --name NAME --file MEMBER.yaml\nsidecar detach APP --name NAME", "Use --server NAME to select a controller. Changes require plan review."},
	"product":        {"product plan --file FILE\nproduct deploy --file FILE", "Use --server NAME to select a controller."},
	"workflow":       {"workflow list APP\nworkflow inspect APP STEP\nworkflow reconcile APP STEP", "Use --server NAME to select a controller. Inspect before reconciling."},
	"resource":       {"resource list\nresource status NAME\nresource logs NAME [--follow]\nresource create TYPE NAME --storage SIZE\nresource scale NAME --cpu CORES --memory SIZE\nresource backup NAME [--output FILE]\nresource restore TYPE NAME --storage SIZE --backup ID\nresource start|stop|restart|delete NAME", "TYPE: postgres, redis or neo4j. Use --server NAME to select a controller.\nFor exports, upgrades and cutover: hostlier skills show resource"},
	"secret":         {"secret list\nsecret set NAME [--stdin | --from-env VARIABLE] [--app APP]\nsecret delete NAME", "Use --app APP to bind a new secret to one application; a successful purge removes it. Omit input flags for a hidden prompt. Use --server NAME to select a controller.\nNever pass secret values as command arguments."},
	"backup":         {"backup destinations\nbackup policy NAME --resource DB --destination ID --every 24h --retain 7\nbackup run NAME [--watch]\nbackup job ID [--watch]\nbackup objects DESTINATION\nbackup import OBJECT_ID --destination ID", "Use --server NAME to select a controller."},
	"connect":        {"connect https://CONTROLLER [--name PROFILE]\nconnect USER@HOST\nconnect [PROFILE]", "One connection flow for setup and renewal. Opens browser approval by default.\nFirst-time setup prompts for SSH administrator access; --ssh supplies it upfront.\nOmit PROFILE to renew the selected server. Existing profiles retain their authentication method.\nAdvanced methods: hostlier skills show connect"},
	"reauth":         {"reauth [PROFILE]", "Alias for connect PROFILE. Uses the same saved authentication method and preserves the profile on cancellation."},
	"disconnect":     {"disconnect [--server NAME]", ""},
	"server":         {"server list [MASTER]\nserver use PROFILE|[MASTER/]BOX\nserver add USER@HOST\nserver join MASTER", ""},
	"domains":        {"domains list\ndomains add HOSTNAME\ndomains remove HOSTNAME", "Use --server NAME to select a controller."},
	"tunnel":         {"tunnel create NAME --bridge-id ID --from-env TOKEN_ENV [--for 24h] [--connections N]\ntunnel list\ntunnel status NAME\ntunnel revoke NAME", ""},
	"fused":          {"fused status\nfused provision NAME --file BUILD/artifact/hostlier-pending.json\nfused bind NAME --file BUILD/artifact/hostlier-pending.json\nfused connect NAME --engine-url HTTPS_ORIGIN --client-id ID [--client-secret-ref SECRET]\nfused token NAME --family-id UUID --secret-name SECRET --name TOKEN --allow OP[,OP]\nfused refresh NAME\nfused disconnect NAME", ""},
	"approve":        {"approve CODE --key FILE [--url https://CONTROLLER]", "Run in your trusted terminal to approve the reviewed request."},
	"approval":       {"approval ID [--watch]", "Resume observing an existing approval request."},
	"authorize":      {"authorize --device ID --on local|HOST --app APP[,APP] --scope deploy --for 2h", "Optional: --max-uses N, --secrets NAME[,NAME], --key FILE.\nSandbox: replace --app with --app-prefix try- --max-apps N [--route-domain try.apps.example.com] [--keep-apps] (local only).\nReview the scope and duration of the deployment window."},
	"authorizations": {"authorizations list\nauthorizations revoke ID", ""},
	"security":       {"security status\nsecurity keygen --key FILE\nsecurity enroll --name OWNER --public-key FILE.pub --socket PATH\nsecurity revoke --fingerprint SHA256:... --socket PATH", "Key generation runs in your trusted terminal. Enrollment is local administration."},
	"pairing":        {"pairing create [--name DEVICE]\npairing list\npairing cancel ID\npairing code ID --socket PATH [--app APP --for 2h --max-uses 20]", "Omit permission flags for all access, no expiry and unlimited uses. For restricted enrollment: hostlier skills show pairing"},
	"clients":        {"clients list\nclients revoke ID", "Use --server NAME to select a controller."},
	"init":           {"init [--detect | --package NAME [--ui]] [--directory DIR] [--service NAME] [--compose FILE] [--dependencies none|apps|sidecars|NAME=MODE,...] [--name NAME] [--port PORT] [--route DOMAIN] [--architecture amd64|arm64] [--dry-run]", "Create the starter .hostlier. Use package add NAME to add package inputs, init --package NAME to run its initializer, or init --detect for app discovery.\nUse --context DIR or --image IMAGE for explicit sources. Server setup: hostlier-controller init."},
	"controller":     {"controller status\ncontroller logs [--operation ID] [--follow]\ncontroller backup --output FILE\ncontroller restore --input FILE --state-dir DIR --source-stopped", "Backup and restore require the separate hostlier-controller executable.\nDaemon configuration: hostlier-controller --help"},
	"hosts":          {"hosts list\nhosts identity\nhosts enroll NAME --url https://HOST:PORT --fingerprint SHA256\nhosts revoke NAME", ""},
	"agent":          {"agent run --controller-fingerprint SHA256 --host ADDRESS --port PORT", "Requires the separate hostlier-controller executable."},
	"doctor":         {"doctor [--server NAME] [--json]", ""},
	"ui":             {"ui [--server NAME] [--port PORT]", "Open the local dashboard and link or select a controller."},
	"operation":      {"operation ID [--watch] [--cursor CURSOR] [--server NAME]", "--watch follows progress. Ctrl-C leaves the operation running."},
	"telemetry":      {"telemetry metrics|logs [--app APP] [--component NAME] [--limit N] [--server NAME]\ntelemetry render --runtime docker|k3s --url https://CONTROLLER --output NEW_DIRECTORY\ntelemetry token --name COLLECTOR --socket PATH\ntelemetry collectors --socket PATH\ntelemetry revoke ID --socket PATH", "render prepares configuration without deploying it. token prints the secret once."},
	"package":        {"package add NAME [--state-dir DIR]\npackage available [--repository GIT_URL | --github OWNER/REPO] [--version REF]\npackage list [--server NAME]\npackage describe NAME [--server NAME]\npackage install NAME --version REF [--repository GIT_URL | --github OWNER/REPO]\npackage install NAME --file BINARY", "Add scaffolds inputs from the locally installed package in .hostlier. Use --server NAME to install on a controller."},
	"sdk":            {"sdk install cloud [--directory NODE_PROJECT]\nsdk install cloud-go [--directory GO_PROJECT]\nsdk credential export --server PROFILE --output PRIVATE_FILE\nsdk install --version TAG_OR_COMMIT [--directory GO_PROJECT]", "Cloud and cloud-go install standalone clients. Create an owner-approved signed profile with hostlier connect, then export one private credential file for direct controller API calls. The versioned form installs the separate Go package-authoring SDK."},
	"skills":         {"skills list [--json]\nskills show COMMAND [--json]\nskills install [COMMAND] [--target codex|claude] [--global] [--dry-run]\nskills install [COMMAND] --output DIRECTORY [--dry-run]", "Omit COMMAND to install all bundled skills. Default: .agents/skills in the project.\nUse --force to replace differing files. All skills commands work offline."},
}
